/**
 * ۱. نفوس مرده — نیکلای گوگول
 */
object Story1 {

    fun get(): StoryContent = StoryContent(
        storyId = "adv_dead_souls",
        chapters = listOf(
            chapter1(),
            chapter2(),
            chapter3(),
            chapter4(),
            chapter5(),
            chapter6(),
        )
    )

    // ─────────── فصل ۱: ورود چیچیکوف ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Arrival of Chichikov", titlePersian = "ورود چیچیکوف",
        paragraphs = listOf(
            StoryParagraph("Into the gates of the provincial town of N—— there drove a rather handsome, small spring carriage of the sort bachelors ride in.", "به دروازه‌های شهر استانی ن—— کالسکه کوچک و بهاری نسبتاً شکیل که مجردها سوار می‌شوند وارد شد."),
            StoryParagraph("In the carriage sat a gentleman, not handsome, but not bad-looking either, neither too fat nor too thin; one could not call him old, but neither could one say he was young.", "در کالسکه نجیب‌زاده‌ای نشسته بود، نه خوش‌قیافه، اما بدقیافه هم نبود، نه خیلی چاق و نه خیلی لاغر؛ نه می‌شد پیر صدایش زد و نه می‌شد گفت جوان است."),
            StoryParagraph("He was neither stout nor lean, but rather a man of middling years and middling build, the sort of man one meets at every turn and yet never truly notices.", "نه فربه بود و نه لاغر، بلکه مردی میان‌سال و با اندامی میانه بود، از آن نوع مردانی که در هر قدم می‌بینی و با این حال هرگز واقعاً متوجهشان نمی‌شوی."),
            StoryParagraph("His name was Pavel Ivanovich Chichikov, and he had come to this town on a matter of business, though he was careful not to reveal exactly what that business was.", "نامش پاول ایوانوویچ چیچیکوف بود و به کاری به این شهر آمده بود، هرچند مراقب بود دقیقاً فاش نکند آن کار چیست."),
            StoryParagraph("The inn where he took lodgings was of the common sort, the kind that can be found in provincial towns anywhere in Russia: shabby, cheap, and filled with the smell of cabbage and stale tobacco.", "مهمان‌خانه‌ای که در آن اقامت گزید از نوع معمولی بود، همان نوعی که در هر شهر استانی روسیه می‌شود یافت: ژنده، ارزان و پر از بوی کلم و تنباکوی مانده."),
            StoryParagraph("But Chichikov did not complain about the accommodations; he was not a man who complained about anything, unless it was to his own advantage to do so.", "اما چیچیکوف از محل اقامت شکایت نکرد؛ او مردی نبود که از چیزی شکایت کند، مگر آنکه شکایت کردن به نفعش بود."),
            StoryParagraph("The next morning, after a hearty breakfast, he began to make the rounds of the town's officials, paying his respects to the governor, the vice-governor, the prosecutor, the chief of police, and every other dignitary of consequence.", "صبح روز بعد، پس از صبحانه‌ای مفصل، شروع کرد به گشت زدن به دیدن مقامات شهر، احترام گذاشتن به فرماندار، معاون فرماندار، دادستان، رئیس پلیس و هر مقام مهم دیگری."),
            StoryParagraph("He was, everyone soon agreed, a most agreeable man; he knew how to flatter without seeming to flatter, to praise without seeming to praise, to make each person feel that he was, in fact, the most important person in the room.", "همه به‌زودی توافق کردند که او مردی بسیار خوش‌مشرب است؛ می‌دانست چطور بدون آنکه به نظر برسد تملق گوید، بدون آنکه به نظر برسد تعریف کند، هر شخص را وادار کند حس کند که در واقع مهم‌ترین شخص اتاق است."),
            StoryParagraph("He could speak with equal ease about horses, about dogs, about politics, about cards, about literature, about virtue, and about the price of grain; there was no subject on which he did not have an opinion, and no opinion which he could not adjust to suit his listener.", "او می‌توانست با همان سهولت درباره اسب صحبت کند، درباره سگ، درباره سیاست، درباره ورق، درباره ادبیات، درباره فضیلت و درباره قیمت غله؛ هیچ موضوعی نبود که نظری درباره‌اش نداشته باشد و هیچ نظری که نتواند برای مطابقت با شنونده‌اش تغییر دهد."),
            StoryParagraph("At a party given by the governor, he met the leading landowners of the region, and he charmed them all with his easy manners and his ready conversation.", "در مهمانی‌ای که فرماندار داد، با زمین‌داران برجسته منطقه آشنا شد و همه‌شان را با رفتار آسان و گفتگوی آماده‌اش مسحور کرد."),
            StoryParagraph("He listened patiently to tales of hunting and card-playing, of lawsuits and inheritances, of serfs and harvests, and he told amusing stories of his own, always just amusing enough and never quite revealing anything about himself.", "او با صبر به داستان‌های شکار و ورق‌بازی گوش داد، از دعاوی و ارث، از رعیت‌ها و محصول، و داستان‌های سرگرم‌کننده خودش را تعریف کرد، همیشه به‌اندازه کافی سرگرم‌کننده و هرگز کاملاً چیزی درباره خودش فاش نمی‌کرد."),
            StoryParagraph("Among the landowners were two who especially interested him: Manilov, a sentimental dreamer of vague and pleasant manners, and Sobakevich, a rough and cynical man who looked like a bear in human form.", "میان زمین‌داران دو نفر بودند که به‌ویژه علاقه‌مندش کردند: مانیلوف، رؤیاپردازی احساساتی با رفتار مبهم و دلپذیر و سوباکویچ، مردی خشن و بدبین که شبیه خرسی در قالب انسان بود."),
            StoryParagraph("Chichikov was particularly attentive to these two, and he arranged, before the evening was out, to visit both of them at their estates, on the pretext of admiring their properties.", "چیچیکوف به‌ویژه به این دو توجه داشت و قبل از پایان شب ترتیبی داد که به ملک هر دوی آن‌ها سر بزند، به بهانه تحسین املاکشان."),
            StoryParagraph("But his interest in them was not, as they supposed, an interest in their lands or their serfs; his interest lay in something else entirely, something that no one in the town could have guessed.", "اما علاقه‌اش به آن‌ها، آن‌گونه که آن‌ها گمان می‌کردند، علاقه به زمین‌ها یا رعیت‌هایشان نبود؛ علاقه‌اش کاملاً چیز دیگری بود، چیزی که هیچ‌کس در شهر نمی‌توانست حدس بزند."),
            StoryParagraph("For Chichikov had conceived a plan, a plan of such audacious genius and such questionable morality that it could only have been devised by a man who understood both the greed of the powerful and the gullibility of the weak.", "زیرا چیچیکوف نقشه‌ای کشیده بود، نقشه‌ای با نابغگی جسورانه و اخلاقیات مورد سؤال چنان که فقط مردی می‌توانست طراحی‌اش کند که هم طمع قدرتمندان را می‌فهمید و هم ساده‌لوحی ضعیفان را."),
            StoryParagraph("His plan was to buy 'dead souls' — the serfs who had died since the last census but who were still officially listed as alive on the tax rolls.", "نقشه‌اش خرید «نفوس مرده» بود — رعیت‌هایی که از سرشماری قبلی مرده بودند اما هنوز رسماً به‌عنوان زنده در دفترهای مالیاتی ثبت بودند."),
            StoryParagraph("These dead serfs existed only on paper, and their owners had to pay taxes on them until the next census, which might not come for years.", "این رعیت‌های مرده فقط روی کاغذ وجود داشتند و مالکانشان باید تا سرشماری بعدی که ممکن بود سال‌ها نباشد مالیاتشان را می‌پرداختند."),
            StoryParagraph("Chichikov would offer to take them off the owners' hands, buying the dead serfs at a fraction of their value, promising to pay all the taxes himself.", "چیچیکوف پیشنهاد می‌کرد آن‌ها را از دست مالکان خلاص کند، رعیت‌های مرده را به کسری از ارزششان بخرد، وعده می‌داد خودش تمام مالیات‌ها را بپردازد."),
            StoryParagraph("The owners would be grateful, thinking they had made a good bargain, and Chichikov would acquire hundreds of serfs on paper.", "مالکان سپاسگزار می‌شدند، فکر می‌کردند معامله خوبی کرده‌اند و چیچیکوف صدها رعیت روی کاغذ به دست می‌آورد."),
            StoryParagraph("With these paper serfs, he could mortgage an estate he did not own, or present himself to society as a man of great wealth, or use them as security for loans that he would never repay.", "با این رعیت‌های کاغذی، می‌توانست ملکی که مالکش نبود را گرو بگذارد، یا خود را به‌عنوان مردی با ثروت فراوان به جامعه معرفی کند، یا از آن‌ها به‌عنوان وثیقه وام‌هایی استفاده کند که هرگز پس نمی‌داد."),
            StoryParagraph("It was, in short, a perfect scheme, one that required no capital, no labor, no risk, and that promised a fortune.", "خلاصه، نقشه‌ای بی‌نقص بود، نقشه‌ای که هیچ سرمایه، نه کار، نه خطر می‌خواست و ثروتی وعده می‌داد."),
            StoryParagraph("The only problem was that it required a certain kind of man to execute it: a man without conscience, without shame, without any principle except self-interest.", "تنها مشکل این بود که اجرایش مردی خاص می‌خواست: مردی بدون وجدان، بدون شرم، بدون هیچ اصلی جز منافع خود."),
            StoryParagraph("And Chichikov, whatever else he might have been, was exactly that kind of man.", "و چیچیکوف، هر چه ممکن بود غیر از این باشد، دقیقاً همان نوع مرد بود."),
            StoryParagraph("He had spent his whole life learning to be such a man; he had started as a poor boy in a family of no importance, had been beaten by his father, had been mocked by his schoolmates, had been cheated by his masters.", "تمام عمرش را صرف آموختن چنین مردی بودن کرده بود؛ به‌عنوان پسری فقیر در خانواده‌ای بی‌اهمیت شروع کرده بود، پدرش کتکش زده بود، هم‌کلاسی‌هایش مسخره‌اش کرده بودند، اربابانش فریبش داده بودند."),
            StoryParagraph("And from all these experiences, he had learned a single lesson: that the only thing worth pursuing in this world was money, and that no means were too base if they led to that end.", "و از همه این تجربیات، یک درس واحد آموخته بود: تنها چیزی که در این دنیا ارزش دنبال کردن دارد پول است و هیچ وسیله‌ای برای رسیدن به آن هدف بیش از حد پست نیست."),
            StoryParagraph("He had served in the customs, and had grown rich by smuggling, until he was caught and dismissed; he had been a clerk in a court of law, and had grown rich by taking bribes, until he was dismissed again.", "در گمرک خدمت کرده بود و از قاچاق ثروتمند شده بود، تا وقتی دستگیر و اخراج شد؛ منشی دادگاه شده بود و از رشوه ثروتمند شده بود، تا وقتی دوباره اخراج شد."),
            StoryParagraph("But each time he was dismissed, he rose again, more cunning, more careful, more cynical, until he had conceived this latest and greatest of his schemes.", "اما هر بار که اخراج می‌شد، دوباره برمی‌خاست، حیله‌گرتر، محتاط‌تر، بدبین‌تر، تا وقتی این آخرین و بزرگ‌ترین نقشه‌اش را طراحی کرد."),
            StoryParagraph("And so Chichikov sat in his inn, in the provincial town of N——, drinking tea and planning his visits to the landowners, confident that his scheme would succeed, confident that he would soon be rich.", "و اینگونه چیچیکوف در مهمان‌خانه‌اش در شهر استانی ن—— نشست، چای می‌نوشید و برای دیدارهایش از زمین‌داران نقشه می‌کشید، مطمئن که نقشه‌اش موفق می‌شود، مطمئن که به‌زودی ثروتمند خواهد شد."),
            StoryParagraph("He did not know that fate had other plans for him; he did not know that his journey through the provinces would become a journey through the soul of Russia itself.", "نمی‌دانست که تقدیر نقشه‌های دیگری برایش دارد؛ نمی‌دانست که سفرش از میان ولایات به سفری از میان روح خود روسیه تبدیل می‌شود."),
            StoryParagraph("He did not know that he would meet, along the way, men of every kind and character: dreamers, cynics, gluttons, misers, fools, and knaves.", "نمی‌دانست که در طول راه با مردانی از هر نوع و شخصیت روبه‌رو می‌شود: رؤیاپردازان، بدبینان، شکم‌پرستان، خسیسان، احمقان و شیادان."),
            StoryParagraph("And he did not know that the Russia he was traveling through was itself a kind of dead soul, a nation that had lost its way, a people that had forgotten what it meant to be alive.", "و نمی‌دانست که روسیه‌ای که در آن سفر می‌کرد خودش نوعی روح مرده بود، ملتی که راهش را گم کرده بود، مردمی که فراموش کرده بودند زنده بودن یعنی چه."),
            StoryParagraph("But all of that was still to come; for now, there was only the road ahead, the carriages, the estates, the landowners, and the endless, beautiful, tragic landscape of the Russian countryside.", "اما همه این‌ها هنوز در راه بود؛ برای اکنون، تنها جاده پیش رو بود، کالسکه‌ها، املاک، زمین‌داران و منظره بی‌پایان، زیبا و تراژیک حومه روسیه."),
            StoryParagraph("And there was Chichikov, sitting in his inn, drinking his tea, waiting for the morning, when he would set out to begin his great and terrible enterprise.", "و چیچیکوف بود، در مهمان‌خانه‌اش نشسته، چایش را می‌نوشید، منتظر صبح، وقتی که برای آغاز کار بزرگ و هولناکش راه می‌افتاد.")
        )
    )

    // ─────────── فصل ۲: مانیلوف ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Manilov", titlePersian = "مانیلوف",
        paragraphs = listOf(
            StoryParagraph("The first landowner whom Chichikov visited was Manilov, a man whose estate was said to be one of the finest in the region.", "نخستین زمین‌داری که چیچیکوف به دیدارش رفت مانیلوف بود، مردی که می‌گفتند ملکش یکی از بهترین‌های منطقه است."),
            StoryParagraph("The road to Manilov's estate was long and dull, running through endless fields of wheat and rye, past villages whose peasants stared in silence at the passing carriage.", "جاده به ملک مانیلوف طولانی و کسل‌کننده بود، از میان مزارع بی‌پایان گندم و چاودار می‌گذشت، از دهکده‌هایی که رعیت‌هایشان در سکوت به کالسکه در حال عبور خیره می‌شدند."),
            StoryParagraph("Chichikov sat in his carriage and watched the landscape pass, and he thought about the interview ahead, planning his words, rehearsing his arguments, preparing to be as charming as he knew how to be.", "چیچیکوف در کالسکه‌اش نشسته بود و منظره در حال گذر را تماشا می‌کرد و به مصاحبه پیش رو فکر می‌کرد، کلماتش را برنامه‌ریزی می‌کرد، استدلال‌هایش را تمرین می‌کرد، آماده می‌شد تا آنقدر که می‌دانست چطور جذاب باشد."),
            StoryParagraph("Manilov's estate was set on a hill, and it was indeed a pretty sight: the white walls of the house gleamed in the morning sun, the garden was full of flowers, and there was even a small pond with ducks swimming on it.", "ملک مانیلوف روی تپه‌ای قرار داشت و واقعاً منظره زیبایی بود: دیوارهای سفید خانه در آفتاب صبح می‌درخشیدند، باغ پر از گل بود و حتی برکه کوچکی با اردک‌هایی که رویش شنا می‌کردند وجود داشت."),
            StoryParagraph("But there was also something disappointing about it, something that did not quite live up to its promise, as though the estate had been planned by a man who loved the idea of an estate more than the estate itself.", "اما چیزی ناامیدکننده هم درباره‌اش بود، چیزی که کاملاً به وعده‌اش عمل نمی‌کرد، گویی ملک توسط مردی طراحی شده بود که ایده ملک را بیشتر از خودش دوست داشت."),
            StoryParagraph("The garden had gone to seed in places; the fence was broken; the pond was green with algae; and the village houses of the serfs were as shabby here as anywhere else.", "باغ در جاهایی به علف هرز افتاده بود؛ حصار شکسته بود؛ برکه با جلبک سبز شده بود؛ و خانه‌های رعیت‌های دهکده اینجا هم مثل هر جای دیگری ژنده بودند."),
            StoryParagraph("Manilov himself came out to greet Chichikov with the enthusiasm of a man who had few visitors and was delighted to have any.", "خود مانیلوف با اشتیاق مردی که بازدیدکنندگان اندکی داشت و از داشتن هر بازدیدکننده‌ای خوشحال بود برای استقبال از چیچیکوف بیرون آمد."),
            StoryParagraph("He was a fair-haired man of middle age, with blue eyes and a smile that seemed permanently fixed on his lips, and he greeted Chichikov as though he were a long-lost brother.", "او مردی بور و میان‌سال بود، با چشمان آبی و لبخندی که به نظر می‌رسید برای همیشه روی لبش نشسته و چیچیکوف را طوری خوش‌آمد گفت گویی برادری گم‌شده است."),
            StoryParagraph("'Pavel Ivanovich!' he cried. 'How delightful! How truly delightful! I cannot tell you how delighted I am to see you!'", "فریاد زد: «پاول ایوانوویچ! چه لذت‌بخش! چه واقعاً لذت‌بخش! نمی‌توانم بگویم چقدر از دیدن شما خوشحالم!»"),
            StoryParagraph("And he shook Chichikov's hand, and embraced him, and held him at arm's length, and looked at him with tears of joy in his eyes.", "و دست چیچیکوف را فشرد، او را در آغوش گرفت، در فاصله بازو نگهش داشت و با اشک شادی در چشمانش نگاهش کرد."),
            StoryParagraph("Chichikov, who had seen such effusions before, responded with appropriate warmth, and the two men went into the house together, arm in arm, as though they had been friends for years.", "چیچیکوف که چنین ابراز احساساتی را قبلاً دیده بود، با گرمای مناسب پاسخ داد و دو مرد با هم وارد خانه شدند، بازو در بازو، گویی سال‌ها دوست بودند."),
            StoryParagraph("The inside of the house was as disappointing as the outside: the furniture was old and worn, the wallpaper was faded, the pictures on the walls were of no particular merit.", "داخل خانه به همان اندازه بیرونش ناامیدکننده بود: مبلمان قدیمی و فرسوده، کاغذ دیواری محو، تصاویر روی دیوارها بدون ارزش خاصی."),
            StoryParagraph("But Manilov did not seem to notice; he spoke of his house as though it were a palace, of his garden as though it were a paradise, of his children as though they were prodigies.", "اما مانیلوف به نظر نمی‌رسید متوجه باشد؛ از خانه‌اش مثل کاخ حرف می‌زد، از باغش مثل بهشت، از بچه‌هایش مثل نوابغ."),
            StoryParagraph("He had two sons, whom he had named Themistocles and Alcibiades, after the Greek heroes, and he spoke of their education with a pride that was entirely unfounded.", "او دو پسر داشت که آن‌ها را به نام تمیستوکلس و آلکیبیادس، به افتخار قهرمانان یونانی، نامیده بود و از تحصیلشان با افتخاری کاملاً بی‌اساس حرف می‌زد."),
            StoryParagraph("'Themistocles,' he said, 'will one day be a great general; he has already shown a remarkable aptitude for military matters.'", "می‌گفت: «تمیستوکلس روزی ژنرال بزرگی می‌شود؛ از قبل استعداد قابل توجهی برای امور نظامی نشان داده است.»"),
            StoryParagraph("'And Alcibiades,' he continued, 'will be a diplomat; he has a way with words that will take him far.'", "ادامه داد: «و آلکیبیادس دیپلمات می‌شود؛ در کلمات استعدادی دارد که او را دور خواهد برد.»"),
            StoryParagraph("Chichikov listened politely, and made the appropriate admiring comments, and all the while he was studying his host, assessing his character, calculating how best to approach the delicate subject that had brought him here.", "چیچیکوف مؤدبانه گوش داد و تعریف‌های تحسین‌آمیز مناسب گفت و در تمام این مدت میزبانش را مطالعه می‌کرد، شخصیتش را ارزیابی می‌کرد، محاسبه می‌کرد چطور بهترین شکل به موضوع حساسی که او را به اینجا آورده بود نزدیک شود."),
            StoryParagraph("He saw that Manilov was a man who lived in a world of his own imagination, a world in which everything was beautiful and noble and good, a world that had very little to do with reality.", "دید مانیلوف مردی است که در جهان تخیل خودش زندگی می‌کند، جهانی که در آن همه چیز زیبا و نجیب و خوب است، جهانی که ربط بسیار کمی به واقعیت دارد."),
            StoryParagraph("Such a man, Chichikov knew, would be easy to manipulate, because he would not understand what he was being manipulated into, and would not believe it even if he were told.", "چیچیکوف می‌دانست چنین مردی دستکاری‌اش آسان است، چون نمی‌فهمد چه چیزی دستکاری می‌شود و باورش هم نمی‌کند اگر به او بگویند."),
            StoryParagraph("After dinner, when the two men were sitting in the drawing room, Chichikov decided that the time had come to introduce his proposal.", "بعد از شام، وقتی دو مرد در نشیمن نشسته بودند، چیچیکوف تصمیم گرفت که وقت ارائه پیشنهادش رسیده است."),
            StoryParagraph("He began by speaking of the state of the country, of the difficulties faced by landowners, of the burden of taxes that fell upon them.", "با صحبت کردن درباره وضعیت کشور شروع کرد، درباره دشواری‌هایی که زمین‌داران با آن روبرو بودند، درباره بار مالیات‌هایی که بر آن‌ها می‌افتاد."),
            StoryParagraph("Manilov agreed with everything he said, and sighed, and spoke of the decline of agriculture, of the idleness of the peasants, of the general decay of the times.", "مانیلوف با هر چه می‌گفت موافق بود و آه کشید و از افول کشاورزی گفت، از تنبلی رعیت‌ها، از انحطاط عمومی زمانه."),
            StoryParagraph("Then Chichikov introduced the question that had brought him here: the question of the dead serfs who were still listed as alive on the tax rolls.", "سپس چیچیکوف پرسشی را که او را به اینجا آورده بود مطرح کرد: پرسش رعیت‌های مرده‌ای که هنوز به‌عنوان زنده در دفترهای مالیاتی ثبت بودند."),
            StoryParagraph("'I have heard,' he said, 'that many landowners would be glad to be rid of these dead souls, which are of no use to anyone but only cost money in taxes.'", "گفت: «شنیده‌ام که بسیاری از زمین‌داران خوشحال می‌شوند از شر این نفوس مرده خلاص شوند، که به هیچ‌کس فایده‌ای نمی‌دهند و فقط پول در مالیات می‌خورند.»"),
            StoryParagraph("'Would you,' he continued, 'be willing to sell me your dead serfs? I would take them off your hands for a small sum, and I would pay all the taxes on them myself.'", "ادامه داد: «آیا شما حاضرید رعیت‌های مرده‌تان را به من بفروشید؟ آن‌ها را در ازای مبلغ کوچکی از دستتان می‌گیرم و خودم تمام مالیاتشان را می‌پردازم.»"),
            StoryParagraph("Manilov stared at him, and for a long moment, he did not speak; and Chichikov watched him carefully, ready to detect the slightest sign of suspicion or resistance.", "مانیلوف نگاهش کرد و لحظه‌ای طولانی صحبت نکرد؛ و چیچیکوف با دقت تماشایش کرد، آماده که کوچک‌ترین نشانه شک یا مقاومت را تشخیص دهد."),
            StoryParagraph("But Manilov was not suspicious; he was simply confused, because he did not understand what Chichikov was proposing.", "اما مانیلوف شک نکرد؛ فقط گیج بود، چون نمی‌فهمید چیچیکوف چه پیشنهادی می‌دهد."),
            StoryParagraph("'You want to buy my dead serfs?' he said at last. 'Why would you want to do that? What use are dead serfs to anyone?'", "سرانجام گفت: «می‌خواهید رعیت‌های مرده‌ام را بخرم؟ چرا می‌خواهید این کار را بکنید؟ نفوس مرده چه فایده‌ای برای کسی دارند؟»"),
            StoryParagraph("'That,' said Chichikov, with a smile, 'is my business, which I would prefer to keep to myself.'", "چیچیکوف با لبخندی گفت: «این کار من است که ترجیح می‌دهم پیش خودم بمانم.»"),
            StoryParagraph("'But is it legal?' asked Manilov. 'Is it permitted?'", "مانیلوف پرسید: «اما قانونی است؟ مجاز است؟»"),
            StoryParagraph("'Certainly it is legal,' said Chichikov. 'Everything is permitted that is not expressly forbidden, and the law says nothing about selling dead serfs.'", "چیچیکوف گفت: «قطعاً قانونی است. هر چیزی که صریحاً ممنوع نشده باشد مجاز است و قانون چیزی درباره فروش نفوس مرده نمی‌گوید.»"),
            StoryParagraph("Manilov thought about this for a moment, and then he smiled, because he had suddenly understood that Chichikov was doing him a great kindness.", "مانیلوف لحظه‌ای به این فکر کرد و بعد لبخند زد، چون ناگهان فهمید چیچیکوف لطف بزرگی به او می‌کند."),
            StoryParagraph("'Well, then,' he said, 'if it is legal, and if you are willing to take these serfs off my hands, I shall be only too happy to do so.'", "گفت: «خب، پس، اگر قانونی است و اگر حاضرید این رعیت‌ها را از دستم خلاص کنید، من فقط بسیار خوشحال می‌شوم این کار را بکنم.»"),
            StoryParagraph("'Excellent,' said Chichikov. 'Then I shall draw up the papers tomorrow.'", "چیچیکوف گفت: «عالی. پس فردا کاغذها را آماده می‌کنم.»"),
            StoryParagraph("But Manilov, who was, in his own way, a generous man, insisted that he would not take money for the dead serfs; he would give them to Chichikov as a gift, freely, in friendship.", "اما مانیلوف که به شیوه خودش مردی سخاوتمند بود، اصرار کرد که برای نفوس مرده پول نمی‌گیرد؛ آن‌ها را به‌عنوان هدیه به چیچیکوف می‌دهد، آزادانه، از دوستی."),
            StoryParagraph("Chichikov thanked him, but insisted that he would pay for the serfs, because he did not want to take advantage of a friend's generosity.", "چیچیکوف تشکر کرد اما اصرار کرد پولشان را می‌پردازد، چون نمی‌خواهد از سخاوت دوست سوءاستفاده کند."),
            StoryParagraph("But Manilov would not hear of it; he would give the dead serfs away for nothing, and he would consider himself fortunate to have been of service to such a distinguished gentleman.", "اما مانیلوف قبول نمی‌کرد؛ نفوس مرده را مجانی می‌داد و خودش را خوش‌شانس می‌دانست که به چنین نجیب‌زاده برجسته‌ای خدمت کرده است."),
            StoryParagraph("And so it was agreed, and Chichikov left Manilov's estate the next morning with a document listing more than a hundred dead serfs, and with a new friend whom he had no intention of ever seeing again.", "و اینگونه توافق شد و چیچیکوف صبح روز بعد ملک مانیلوف را با سندی که بیش از صد رعیت مرده را فهرست می‌کرد و با دوست جدیدی که هیچ قصدی نداشت هرگز دوباره ببیندش ترک کرد."),
            StoryParagraph("As the carriage drove away from the estate, Chichikov looked back at the white house on the hill, and he smiled a small, knowing smile.", "وقتی کالسکه از ملک دور می‌شد، چیچیکوف به خانه سفید روی تپه نگاه کرد و لبخند کوچکی زد، لبخندی دانا."),
            StoryParagraph("'Sentimental fool,' he thought. 'He gave me a hundred dead souls for nothing, and he thinks he has done me a great favor.'", "فکر کرد: «ابله احساساتی. صد روح مرده را مجانی به من داد و فکر می‌کند لطف بزرگی به من کرده.»"),
            StoryParagraph("'If all the landowners in Russia are like him,' he continued to himself, 'my fortune is as good as made.'", "با خودش ادامه داد: «اگر همه زمین‌داران روسیه مثل او باشند، ثروتم قطعاً درست شده است.»"),
            StoryParagraph("But he was soon to discover that not all landowners were like Manilov, and that some of them would be much harder to deal with.", "اما به‌زودی می‌فهمید که همه زمین‌داران مثل مانیلوف نیستند و با بعضی‌شان برخورد بسیار دشوارتر است."),
            StoryParagraph("The road to his next destination stretched ahead of him, and the carriage rolled on through the endless Russian countryside, and Chichikov settled back into his seat, thinking of the fortune that awaited him.", "جاده به مقصد بعدی‌اش پیش رویش کشیده شده بود و کالسکه در حومه بی‌پایان روسیه می‌غلتید و چیچیکوف در جای خودش جا گرفت، به ثروتی که در انتظارش بود فکر می‌کرد."),
            StoryParagraph("The sun was setting, and the fields were golden in its light, and there was a beauty to the landscape that even Chichikov could not help but notice.", "خورشید غروب می‌کرد و مزارع در نورش طلایی بودند و زیبایی‌ای در منظره بود که حتی چیچیکوف هم نمی‌توانست متوجه‌اش نشود."),
            StoryParagraph("For a moment, as he watched the sun sink behind the wheat fields, he felt something stir in his chest, something that might have been emotion, might have been longing, might have been the ghost of a soul.", "برای لحظه‌ای، همان‌طور که تماشا می‌کرد خورشید پشت مزارع گندم فرو می‌رود، چیزی در سینه‌اش تکان خورد، چیزی که می‌توانست احساس باشد، می‌توانست اشتیاق، می‌توانست شبح یک روح."),
            StoryParagraph("But the moment passed, and he was Chichikov again, practical and calculating, thinking of his fortune and his future, and the dead souls he had come to this godforsaken province to collect.", "اما لحظه گذشت و دوباره چیچیکوف شد، عملی و محاسبه‌گر، به ثروت و آینده‌اش فکر می‌کرد و نفوس مرده‌ای که به این ولایت نفرین‌شده آمده بود جمع کند.")
        )
    )

    // ─────────── فصل ۳: سوباکویچ ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Sobakevich", titlePersian = "سوباکویچ",
        paragraphs = listOf(
            StoryParagraph("Chichikov's next visit was to Sobakevich, and the contrast with Manilov could not have been greater.", "دیدار بعدی چیچیکوف از سوباکویچ بود و تضاد با مانیلوف نمی‌توانست بیشتر باشد."),
            StoryParagraph("Where Manilov had been soft, sentimental, and vague, Sobakevich was hard, practical, and precise, and he was also the most suspicious man Chichikov had ever met.", "جایی که مانیلوف نرم و احساساتی و مبهم بود، سوباکویچ سخت و عملی و دقیق بود و همچنین مشکوک‌ترین مردی که چیچیکوف هرگز دیده بود."),
            StoryParagraph("Sobakevich lived in a house that seemed to have been built for a bear, and indeed, Sobakevich himself resembled a bear in every respect: his face, his movements, his way of standing on two legs as though he would have been more comfortable on four.", "سوباکویچ در خانه‌ای زندگی می‌کرد که به نظر می‌رسید برای خرس ساخته شده و در واقع، خودش از هر نظر شبیه خرس بود: چهره‌اش، حرکاتش، شیوه‌ای که روی دو پا می‌ایستاد گویی روی چهار پا راحت‌تر بود."),
            StoryParagraph("Even his name, Sobakevich, came from the Russian word for dog, and his personality matched his name: he was fierce, loyal to no one but himself, and always ready to bite.", "حتی نامش، سوباکویچ، از واژه روسی سگ می‌آمد و شخصیتش با نامش جور بود: وحشی بود، به هیچ‌کس جز خودش وفادار نبود و همیشه آماده گاز گرفتن."),
            StoryParagraph("His house was as heavy and solid as its owner, with thick walls, small windows, and furniture that seemed designed to support the weight of an army.", "خانه‌اش به همان سنگینی و استحکام صاحبش بود، با دیوارهای ضخیم، پنجره‌های کوچک و مبلمانی که به نظر می‌رسید برای تحمل وزن یک ارتش طراحی شده."),
            StoryParagraph("Every chair, every table, every bed seemed to say, 'I am Sobakevich, and I am as solid and unmovable as the earth itself.'", "هر صندلی، هر میز، هر تخت به نظر می‌رسید می‌گوید: «من سوباکویچم و مثل خود زمین محکم و تکان‌ناپذیرم.»"),
            StoryParagraph("When Chichikov arrived, Sobakevich did not embrace him, did not exclaim with joy, did not offer any of the empty courtesies that Manilov had showered upon him.", "وقتی چیچیکوف رسید، سوباکویچ او را در آغوش نگرفت، از خوشحالی فریاد نزد، هیچ‌کدام از تعارف‌های خالی که مانیلوف بر او ریخته بود را ارائه نکرد."),
            StoryParagraph("He simply grunted, and said, 'Ah, it's you,' and led Chichikov into the house, and asked him, without any preface, what he wanted.", "فقط غرغر کرد و گفت: «آه، تویی،» و چیچیکوف را به داخل خانه برد و بدون هیچ مقدمه‌ای پرسید چه می‌خواهد."),
            StoryParagraph("Chichikov, who was used to more polite treatment, was somewhat taken aback, but he recovered quickly, and he began to explain his business in the same careful, roundabout way he had used with Manilov.", "چیچیکوف که به رفتار مؤدبانه‌تر عادت داشت، کمی جا خورد، اما سریع بهبود یافت و شروع کرد به توضیح کارش به همان شیوه محتاطانه و غیرمستقیم که با مانیلوف به کار برده بود."),
            StoryParagraph("But Sobakevich interrupted him almost immediately, saying, 'You want to buy dead souls. I'll sell them to you. What will you give me for them?'", "اما سوباکویچ تقریباً بلافاصله حرفش را قطع کرد و گفت: «می‌خواهی نفوس مرده بخری. بهت می‌فروشم. چقدر می‌دهی؟»"),
            StoryParagraph("Chichikov was startled; he had not expected the negotiation to proceed so quickly, or so bluntly.", "چیچیکوف شوکه شد؛ انتظار نداشت مذاکره اینقدر سریع یا اینقدر بی‌پرده پیش برود."),
            StoryParagraph("'But how did you know?' he asked. 'I have not yet told you what I want.'", "پرسید: «اما از کجا دانستید؟ من هنوز نگفته‌ام چه می‌خواهم.»"),
            StoryParagraph("'I know everything about everyone in this province,' said Sobakevich. 'I know why you have come, and I know what you want. You want dead souls. You cannot fool me.'", "سوباکویچ گفت: «من همه چیز درباره همه در این ولایت می‌دانم. می‌دانم چرا آمده‌ای و می‌دانم چه می‌خواهی. نفوس مرده می‌خواهی. نمی‌توانی فریبم دهی.»"),
            StoryParagraph("Chichikov realized that he was dealing with a much more dangerous man than Manilov, and he adjusted his strategy accordingly.", "چیچیکوف فهمید با مردی بسیار خطرناک‌تر از مانیلوف سر و کار دارد و استراتژی‌اش را مطابق با آن تنظیم کرد."),
            StoryParagraph("He dropped all pretense, and he began to bargain with Sobakevich in earnest, and the bargaining was long and difficult, because Sobakevich was as hard in business as he was in everything else.", "او تمام تظاهر را رها کرد و شروع کرد به جدی چانه زدن با سوباکویچ و چانه زنی طولانی و دشوار بود، چون سوباکویچ در تجارت به همان اندازه سخت بود که در همه چیز دیگر."),
            StoryParagraph("He insisted that his dead serfs were worth a hundred rubles each, that they had been the strongest and most skilled workers in the province, that it was a crime to sell them for less.", "اصرار کرد که هر یک از رعیت‌های مرده‌اش صد روبل می‌ارزد، که آن‌ها قوی‌ترین و ماهرترین کارگران ولایت بودند، که جنایت است کمتر فروختنشان."),
            StoryParagraph("Chichikov pointed out that dead serfs were, by definition, worth nothing, that they could not work, could not pay taxes, could not do anything at all.", "چیچیکوف اشاره کرد که نفوس مرده به‌خودی‌خود هیچ ارزشی ندارند، نمی‌توانند کار کنند، نمی‌توانند مالیات بدهند، هیچ کاری نمی‌توانند بکنند."),
            StoryParagraph("But Sobakevich would not be moved; he treated the dead serfs as though they were alive, and he haggled over each one as though he were selling a prize horse.", "اما سوباکویچ تکان نمی‌خورد؛ با نفوس مرده مثل اینکه زنده‌اند رفتار می‌کرد و بر سر هر یک چانه می‌زد گویی اسب جایزه‌ای می‌فروشد."),
            StoryParagraph("'Look at this one,' he said, pointing to a name on his list. 'Mikheev, the carriage-maker. There was not a finer carriage-maker in all of Russia. He could make a wheel that would never break.'", "اشاره کرد به نامی در فهرستش و گفت: «به این یکی نگاه کن. میخائف، کالسکه‌ساز. در تمام روسیه کالسکه‌ساز ماهرتری نبود. می‌توانست چرخی بسازد که هرگز نمی‌شکست.»"),
            StoryParagraph("'And this one,' he continued, 'Stepan Probka, the carpenter. I warrant you will never find another carpenter like him.'", "ادامه داد: «و این یکی، استپان پروبکا، نجار. تضمین می‌کنم هرگز نجاری مثل او پیدا نخواهی کرد.»"),
            StoryParagraph("'But they are dead,' Chichikov pointed out. 'Dead men cannot make carriages or build houses.'", "چیچیکوف اشاره کرد: «اما مرده‌اند. مردگان نمی‌توانند کالسکه بسازند یا خانه بسازند.»"),
            StoryParagraph("'Dead or alive, they were the best,' said Sobakevich, 'and I will not sell them for less than a hundred rubles each.'", "سوباکویچ گفت: «مرده یا زنده، بهترین بودند و کمتر از صد روبل هر یک نمی‌فروشم.»"),
            StoryParagraph("Chichikov, seeing that his usual tricks would not work, decided to try a different approach.", "چیچیکوف که دید حیله‌های معمولش کار نمی‌کند تصمیم گرفت رویکرد دیگری امتحان کند."),
            StoryParagraph("He began to speak of the difficulty of the times, of the burden of taxes, of the uncertainty of the future, of the need for men of good will to help each other in times of trouble.", "شروع کرد به صحبت کردن از سختی زمانه، از بار مالیات، از عدم قطعیت آینده، از نیاز مردان خیرخواه به کمک به یکدیگر در مواقع سختی."),
            StoryParagraph("But Sobakevich was not moved by such appeals; he was a man who had never helped anyone but himself, and he did not intend to start now.", "اما سوباکویچ با چنین درخواست‌هایی تحت تأثیر قرار نگرفت؛ او مردی بود که هرگز به کسی جز خودش کمک نکرده بود و قصد نداشت از حالا شروع کند."),
            StoryParagraph("In the end, after hours of haggling, they agreed on a price of two and a half rubles per dead serf, which was a great deal more than Chichikov had wanted to pay, but a great deal less than Sobakevich had wanted to receive.", "در پایان، بعد از ساعت‌ها چانه زدن، بر قیمت دو و نیم روبل برای هر نفس مرده توافق کردند که بسیار بیشتر از آن بود که چیچیکوف می‌خواست بپردازد اما بسیار کمتر از آن بود که سوباکویچ می‌خواست دریافت کند."),
            StoryParagraph("Both men were dissatisfied, and both men suspected that they had been cheated, but both men were too practical to let their dissatisfaction prevent them from closing the deal.", "هر دو مرد ناراضی بودند و هر دو مرد مشکوک بودند فریب خورده‌اند، اما هر دو مرد آنقدر عملی بودند که نگذارند نارضایتی‌شان مانع بستن معامله شود."),
            StoryParagraph("And so Chichikov left Sobakevich's house with another list of dead souls, and with a new respect for the cunning of the Russian landowner.", "و اینگونه چیچیکوف خانه سوباکویچ را با فهرست دیگری از نفوس مرده ترک کرد و با احترام جدیدی برای حیله‌گری زمین‌دار روسی."),
            StoryParagraph("'That one is a real devil,' he thought as he climbed back into his carriage. 'He knew exactly what I wanted, and he made me pay for it.'", "وقتی دوباره سوار کالسکه‌اش شد فکر کرد: «او یک شیطان واقعی است. دقیقاً می‌دانست چه می‌خواهم و مجبورم کرد تاوانش را بدهم.»"),
            StoryParagraph("'But at least I have the souls,' he consoled himself. 'Two and a half rubles each is still a bargain for what I intend to do with them.'", "خودش را دلداری داد: «اما دست‌کم نفوس را دارم. هر یک دو و نیم روبل هنوز معامله خوبی است برای کاری که قصد دارم با آن‌ها بکنم.»"),
            StoryParagraph("'And if all the landowners are as clever as Sobakevich, I shall have to be even cleverer.'", "«و اگر همه زمین‌داران به باهوشی سوباکویچ باشند، باید حتی باهوش‌تر باشم.»"),
            StoryParagraph("He laughed to himself, and the carriage rolled on, and the sun continued to sink towards the horizon, and the endless Russian fields stretched out on every side, vast and empty and strangely beautiful.", "او به خودش خندید و کالسکه به راهش ادامه داد و خورشید به غروب ادامه داد و مزارع بی‌پایان روسیه از هر طرف کشیده شده بودند، عظیم و خالی و به‌طرز عجیبی زیبا."),
            StoryParagraph("And Chichikov sat in his carriage, dreaming of the fortune that awaited him, and thinking, with satisfaction, of the clever scheme that would soon make him one of the richest men in Russia.", "و چیچیکوف در کالسکه‌اش نشست، در خواب ثروتی که در انتظارش بود و به رضایت به نقشه زیرکانه‌ای که به‌زودی او را یکی از ثروتمندترین مردان روسیه می‌کرد فکر می‌کرد."),
            StoryParagraph("He did not know that his scheme was doomed to fail, that word of his strange purchases was already spreading, that the landowners of the province were beginning to ask questions.", "نمی‌دانست نقشه‌اش محکوم به شکست است، خبر خریدهای عجیبش از قبل پخش می‌شد، زمین‌داران ولایت شروع کرده بودند به سؤال پرسیدن."),
            StoryParagraph("He did not know that his journey through the provinces would soon come to an abrupt and humiliating end.", "نمی‌دانست که سفرش از میان ولایات به‌زودی به پایانی ناگهانی و تحقیرآمیز می‌رسد."),
            StoryParagraph("But all of that was still to come; for now, there was only the road, the carriage, the sunset, and the endless, beautiful, tragic landscape of Russia.", "اما همه این‌ها هنوز در راه بود؛ برای اکنون، تنها جاده بود، کالسکه، غروب و منظره بی‌پایان، زیبا و تراژیک روسیه.")
        )
    )

    // ─────────── فصل ۴: نوزدریوف ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Nozdryov", titlePersian = "نوزدریوف",
        paragraphs = listOf(
            StoryParagraph("The third landowner whom Chichikov visited was Nozdryov, and Nozdryov was unlike any man he had ever met.", "سومین زمین‌داری که چیچیکوف به دیدارش رفت نوزدریوف بود و نوزدریوف مثل هیچ مردی نبود که هرگز دیده بود."),
            StoryParagraph("Where Manilov was soft and Sobakevich was hard, Nozdryov was chaotic, a man of wild impulses and sudden enthusiasms, a man who could not sit still, could not stop talking, could not tell the truth even when the truth would have served him better.", "جایی که مانیلوف نرم بود و سوباکویچ سخت، نوزدریوف آشوبی بود، مردی با تکانه‌های وحشی و اشتیاق‌های ناگهانی، مردی که نمی‌توانست آرام بنشیند، نمی‌توانست از حرف زدن دست بکشد، نمی‌توانست راست بگوید حتی وقتی راست گفتن به نفعش بود."),
            StoryParagraph("He was a gambler, a drinker, a fighter, a liar, and a braggart, and he was also, in his own strange way, the most honest man Chichikov had met in the entire province.", "او قمارباز بود، مشروب‌خوار، دعواجو، دروغگو و لاف‌زن و به شیوه عجیب خودش، صادق‌ترین مردی بود که چیچیکوف در تمام ولایت دیده بود."),
            StoryParagraph("For Nozdryov never pretended to be anything other than what he was; he was a scoundrel, and he knew it, and he did not care who else knew it.", "زیرا نوزدریوف هرگز تظاهر نمی‌کرد چیزی جز آنچه بود باشد؛ او یاغی بود و می‌دانست و اهمیتی نمی‌داد چه کسی دیگر هم می‌داند."),
            StoryParagraph("When Chichikov arrived at his estate, Nozdryov greeted him with the enthusiasm of a man who had been drinking since morning, which, in fact, he had.", "وقتی چیچیکوف به ملکش رسید، نوزدریوف با اشتیاق مردی که از صبح مشروب می‌خورد به استقبالش آمد، که در واقع چنین بود."),
            StoryParagraph("'Ah, Chichikov!' he cried. 'You devil! Where have you been hiding? Come in, come in, we'll drink, we'll play cards, we'll have a fine time!'", "فریاد زد: «آه، چیچیکوف! تو شیطان! کجا قایم شده بودی؟ بیا تو، بیا تو، می‌نوشیم، ورق بازی می‌کنیم، خوش می‌گذرانیم!»"),
            StoryParagraph("And he grabbed Chichikov by the arm and dragged him into the house, and before Chichikov could say a word, Nozdryov had ordered wine and cards and was proposing half a dozen different schemes for how they might spend the day.", "و چیچیکوف را از بازو گرفت و به داخل خانه کشید و قبل از اینکه چیچیکوف کلمه‌ای بگوید، نوزدریوف شراب و ورق سفارش داده بود و نیم دوجین نقشه مختلف برای چگونگی گذراندن روز پیشنهاد می‌کرد."),
            StoryParagraph("'Let's go hunting!' he said. 'I have a fine pack of hounds, and a wolf that I caught last winter, and a horse that I won in a card game.'", "گفت: «برویم شکار! یک گلۀ عالی سگ شکاری دارم و گرگی که زمستان قبل گرفتم و اسبی که در قمار بردم.»"),
            StoryParagraph("'Or let's play cards!' he continued. 'I have a new deck that I have been saving for a special occasion, and I feel lucky today.'", "ادامه داد: «یا ورق بازی کنیم! دست جدیدی دارم که برای مناسبت خاصی نگه داشته‌ام و امروز حس شانس می‌کنم.»"),
            StoryParagraph("'Or let's go visit my neighbor, who has a daughter who is said to be very beautiful, and who is also said to be very rich!'", "«یا برویم به دیدن همسایه‌ام که دختری دارد که می‌گویند خیلی زیباست و می‌گویند خیلی هم ثروتمند است!»"),
            StoryParagraph("Chichikov, who had come for one purpose and one purpose only, tried to steer the conversation towards his business, but Nozdryov would not be steered.", "چیچیکوف که برای یک هدف و تنها یک هدف آمده بود تلاش کرد گفتگو را به سمت کارش هدایت کند، اما نوزدریوف هدایت نمی‌شد."),
            StoryParagraph("Every time Chichikov tried to mention dead souls, Nozdryov would interrupt him with some new scheme or some new story, until Chichikov began to despair of ever making himself understood.", "هر بار که چیچیکوف تلاش می‌کرد به نفوس مرده اشاره کند، نوزدریوف با نقشه‌ای جدید یا داستانی جدید حرفش را قطع می‌کرد، تا وقتی چیچیکوف شروع کرد به ناامیدی از فهمیده شدن."),
            StoryParagraph("Finally, in desperation, Chichikov blurted out what he wanted: to buy Nozdryov's dead serfs.", "سرانجام، در ناامیدی، چیچیکوف بیرون داد چه می‌خواهد: خرید رعیت‌های مرده نوزدریوف."),
            StoryParagraph("Nozdryov stared at him, and for a moment, he was silent.", "نوزدریوف نگاهش کرد و لحظه‌ای ساکت بود."),
            StoryParagraph("Then he burst out laughing.", "بعد ترکید به خنده."),
            StoryParagraph("'Dead souls!' he cried. 'You want to buy dead souls! Why, that's the funniest thing I ever heard! What will you do with them? Will you put them in your pocket? Will you plant them in your garden?'", "فریاد زد: «نفوس مرده! می‌خواهی نفوس مرده بخری! خوب، این خنده‌دارترین چیزی است که شنیده‌ام! با آن‌ها چه می‌کنی؟ در جیبت می‌گذاری؟ در باغت می‌کاری؟»"),
            StoryParagraph("Chichikov tried to explain that his reasons were his own, that he was willing to pay for the dead serfs, that he would take them off Nozdryov's hands.", "چیچیکوف تلاش کرد توضیح دهد دلایلش مال خودش است، حاضر است پول نفوس مرده را بپردازد، از دست نوزدریوف خلاصشان می‌کند."),
            StoryParagraph("But Nozdryov would not sell; or rather, he would sell, but only on terms that Chichikov could not possibly accept.", "اما نوزدریوف نمی‌فروخت؛ یا بهتر، می‌فروخت، اما فقط با شرایطی که چیچیکوف به هیچ وجه نمی‌توانست بپذیرد."),
            StoryParagraph("'I'll sell you the dead souls,' he said, 'but you have to buy my horse too, and my dogs, and my organ, and my carriage.'", "گفت: «نفوس مرده را بهت می‌فروشم، اما باید اسبم را هم بخری، سگ‌هایم را، ارگم را، کالسکه‌ام را.»"),
            StoryParagraph("'Or,' he continued, 'we can play cards for them. If you win, you get the dead souls for nothing. If I win, you pay me a hundred rubles for each one.'", "ادامه داد: «یا، می‌توانیم برای آن‌ها ورق بازی کنیم. اگر ببری، نفوس مرده را مجانی می‌گیری. اگر ببرم، صد روبل برای هر یک به من می‌دهی.»"),
            StoryParagraph("Chichikov refused, knowing that Nozdryov was a cheat, and that the cards would be marked, and that he would lose no matter how well he played.", "چیچیکوف امتناع کرد، چون می‌دانست نوزدریوف تقلبکار است و ورق‌ها نشان‌دار و هر چقدر هم خوب بازی کند می‌بازد."),
            StoryParagraph("Nozdryov, infuriated by the refusal, began to shout, and then to threaten, and then to call for his servants to come and throw Chichikov out of the house.", "نوزدریوف که از رد شدن خشمگین شده بود شروع کرد به فریاد زدن و بعد به تهدید کردن و بعد به صدا زدن نوکرهایش که بیایند و چیچیکوف را از خانه بیرون بیندازند."),
            StoryParagraph("Chichikov, seeing that the situation had become dangerous, fled to his carriage, and ordered his coachman to drive away as fast as the horses could go.", "چیچیکوف که دید وضعیت خطرناک شده به کالسکه‌اش فرار کرد و به کالسکه‌چی‌اش دستور داد آنقدر که اسب‌ها می‌توانند تند براند."),
            StoryParagraph("And so he escaped from Nozdryov's estate without any dead souls, and with a new understanding of how unpredictable and dangerous the Russian provinces could be.", "و اینگونه از ملک نوزدریوف بدون هیچ نفس مرده‌ای فرار کرد و با درک جدیدی از اینکه ولایات روسیه چقدر غیرقابل پیش‌بینی و خطرناک می‌توانند باشند."),
            StoryParagraph("'That one is mad,' he thought, as the carriage rattled down the road. 'Absolutely mad. There is no dealing with a madman.'", "در حالی که کالسکه در جاده می‌لرزید فکر کرد: «آن یکی دیوانه است. کاملاً دیوانه. با دیوانه نمی‌شود کنار آمد.»"),
            StoryParagraph("But even as he fled, he could not help laughing at the absurdity of the encounter, because Nozdryov, for all his faults, had been the most entertaining man he had met in the entire province.", "اما حتی همان‌طور که فرار می‌کرد، نمی‌توانست به پوچی آن برخورد نخندد، چون نوزدریوف با تمام عیب‌هایش سرگرم‌کننده‌ترین مردی بود که در تمام ولایت دیده بود."),
            StoryParagraph("And he knew that he would remember Nozdryov long after he had forgotten Manilov and Sobakevich, because Nozdryov was not merely a landowner, he was a force of nature.", "و می‌دانست که نوزدریوف را خیلی بعد از فراموش کردن مانیلوف و سوباکویچ به یاد می‌آورد، چون نوزدریوف تنها یک زمین‌دار نبود، نیرویی از طبیعت بود."),
            StoryParagraph("The carriage rolled on through the countryside, and Chichikov sat inside, thinking about his narrow escape, and about the difficulties that lay ahead of him in his great and questionable enterprise.", "کالسکه در حومه شهر می‌غلتید و چیچیکوف داخل نشسته بود، به فرار باریکش فکر می‌کرد و به دشواری‌هایی که در کار بزرگ و مورد سؤالش پیش رویش بود."),
            StoryParagraph("He had expected to find greed and stupidity among the landowners, and he had found both, but he had also found something he had not expected: a wild, chaotic, almost admirable vitality that seemed to belong to the Russian character itself.", "انتظار داشت طمع و حماقت میان زمین‌داران بیابد و هر دو را یافته بود، اما چیز دیگری هم یافته بود که انتظارش را نداشت: سرزندگی‌ای وحشی، آشوبی، تقریباً تحسین‌برانگیز که به نظر می‌رسید به خود شخصیت روسی تعلق دارد."),
            StoryParagraph("And that vitality, he suspected, would be both his greatest challenge and his greatest opportunity, because a people who could produce a Nozdryov could also produce anything else, for good or for evil.", "و آن سرزندگی، مشکوک بود، بزرگ‌ترین چالش و بزرگ‌ترین فرصتش می‌بود، چون مردمی که می‌توانند نوزدریوفی تولید کنند می‌توانند هر چیز دیگری هم تولید کنند، چه خوب چه بد.")
        )
    )

    // ─────────── فصل ۵: پلیوشکین ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "Plyushkin", titlePersian = "پلیوشکین",
        paragraphs = listOf(
            StoryParagraph("The last landowner whom Chichikov visited was Plyushkin, and Plyushkin was the strangest man of them all.", "آخرین زمین‌داری که چیچیکوف به دیدارش رفت پلیوشکین بود و پلیوشکین عجیب‌ترین مرد از همه‌شان بود."),
            StoryParagraph("Where the other landowners had been at least recognizable as human beings, Plyushkin had become something less than human, something that only barely resembled a man.", "جایی که سایر زمین‌داران دست‌کم به‌عنوان انسان‌ها قابل تشخیص بودند، پلیوشکین به چیزی کمتر از انسان تبدیل شده بود، چیزی که تنها به‌سختی شبیه مردی بود."),
            StoryParagraph("He was a miser, but not a miser in the ordinary sense; he was a miser consumed by his own avarice, a man who had sacrificed everything to his obsession with hoarding.", "او خسیس بود، اما نه خسیس به معنای معمولی؛ خسیسی بود که توسط طمع خودش بلعیده شده بود، مردی که همه چیز را وقف وسواسش به انباشتن کرده بود."),
            StoryParagraph("Once, he had been a wealthy man, with hundreds of serfs, with a fine house, with a family that loved him.", "زمانی مردی ثروتمند بود، با صدها رعیت، با خانه‌ای زیبا، با خانواده‌ای که دوستش داشت."),
            StoryParagraph("But the death of his wife, the estrangement of his children, the loss of his friends, had all contributed to his decline, and he had turned to hoarding as a way of filling the emptiness inside him.", "اما مرگ همسرش، بیگانگی فرزندانش، از دست دادن دوستانش، همه به افولش کمک کرده بودند و او به انباشتن به‌عنوان راهی برای پر کردن خالی‌بودن درونش پناه برده بود."),
            StoryParagraph("Now he lived in a house that was falling apart, surrounded by piles of garbage, dressed in rags, and yet he owned more wealth than any other landowner in the province.", "حالا در خانه‌ای زندگی می‌کرد که در حال فروریختن بود، احاطه‌شده با توده‌های زباله، پوشیده در ژنده‌ها و با این حال ثروت بیشتری از هر زمین‌دار دیگری در ولایت داشت."),
            StoryParagraph("When Chichikov arrived at his estate, he did not at first recognize the figure shuffling towards him as his host.", "وقتی چیچیکوف به ملکش رسید اول شکلی که به سمتش می‌خزید را به‌عنوان میزبانش تشخیص نداد."),
            StoryParagraph("He took the man for a servant, or a beggar, or perhaps a madman; he was dressed in such tattered rags, and he moved with such uncertainty, and his eyes had such a strange, empty look.", "او آن مرد را نوکر، یا گدا، یا شاید دیوانه فرض کرد؛ اینقدر ژنده پوشیده بود و با چنان عدم قطعیتی حرکت می‌کرد و چشمانش نگاهی عجیب و خالی داشتند."),
            StoryParagraph("'I have come,' said Chichikov, 'to discuss a matter of business with your master, Mr. Plyushkin.'", "چیچیکوف گفت: «آمده‌ام درباره موضوعی تجاری با اربابتان، آقای پلیوشکین، صحبت کنم.»"),
            StoryParagraph("'I am Plyushkin,' said the figure, and Chichikov was struck dumb with astonishment.", "شکل گفت: «من پلیوشکینم.» و چیچیکوف از حیرت لال شد."),
            StoryParagraph("'You must be joking,' he said at last. 'You cannot be Plyushkin.'", "سرانجام گفت: «باید شوخی کنید. شما نمی‌توانید پلیوشکین باشید.»"),
            StoryParagraph("'I am he,' said Plyushkin, without any expression on his face, and he led Chichikov into his house.", "پلیوشکین بدون هیچ حالتی در صورتش گفت: «من او هستم.» و چیچیکوف را به خانه‌اش برد."),
            StoryParagraph("The interior of the house was even more depressing than the exterior: furniture was broken, paintings were covered in dust, and there were piles of junk everywhere, piles that Plyushkin had been accumulating for years.", "داخل خانه حتی از بیرونش افسرده‌کننده‌تر بود: مبلمان شکسته، نقاشی‌ها پوشیده در گرد و غبار و همه‌جا توده‌های آشغال بودند، توده‌هایی که پلیوشکین سال‌ها انباشته بود."),
            StoryParagraph("'I have come,' said Chichikov, 'to make you an offer for some of your... property.'", "چیچیکوف گفت: «آمده‌ام پیشنهادی برای بعضی از... دارایی‌تان به شما بدهم.»"),
            StoryParagraph("'Property?' said Plyushkin, and his eyes flickered with suspicion. 'What property?'", "پلیوشکین گفت: «دارایی؟» و چشمانش از شک برق زد. «چه دارایی؟»"),
            StoryParagraph("'Your dead serfs,' said Chichikov. 'The ones who have died since the last census but who are still listed as alive on the tax rolls.'", "چیچیکوف گفت: «رعیت‌های مرده‌تان. آن‌هایی که از سرشماری قبلی مرده‌اند اما هنوز به‌عنوان زنده در دفترهای مالیاتی ثبت‌اند.»"),
            StoryParagraph("Plyushkin was silent for a long moment, and then, slowly, a strange expression came over his face, an expression that might have been joy, might have been relief, might have been something else entirely.", "پلیوشکین لحظه‌ای طولانی ساکت بود و بعد، آهسته، حالت عجیبی روی صورتش آمد، حالتی که می‌توانست شادی باشد، می‌توانست آسودگی، می‌توانست چیز کاملاً دیگری باشد."),
            StoryParagraph("'You want to buy them?' he said. 'You want to pay me money for dead serfs?'", "گفت: «می‌خواهید بخریدشان؟ می‌خواهید برای نفوس مرده به من پول بدهید؟»"),
            StoryParagraph("'Yes,' said Chichikov. 'I will pay you a small sum for each one.'", "چیچیکوف گفت: «بله. برای هر یک مبلغ کوچکی به شما می‌پردازم.»"),
            StoryParagraph("Plyushkin could hardly believe his ears; he had been paying taxes on these dead serfs for years, and now a stranger had come to take them off his hands, and to pay him for the privilege.", "پلیوشکین به‌سختی می‌توانست گوش‌هایش را باور کند؛ سال‌ها مالیات این نفوس مرده را پرداخته بود و حالا غریبه‌ای آمده بود آن‌ها را از دستش خلاص کند و برای این افتخار به او پول بدهد."),
            StoryParagraph("'How much?' he asked, and his voice was hoarse with greed.", "پرسید: «چقدر؟» و صدایش از طمع خش‌دار بود."),
            StoryParagraph("Chichikov named a price, a very low price, and Plyushkin, who had once bargained over every kopek, agreed without hesitation.", "چیچیکوف قیمتی گفت، قیمتی بسیار پایین و پلیوشکین که زمانی بر سر هر کوپکی چانه می‌زد بدون تردید موافقت کرد."),
            StoryParagraph("'Bring the list,' he said. 'Bring all the lists. Take all the dead serfs you want. Take them for nothing, if you like.'", "گفت: «فهرست را بیاور. همه فهرست‌ها را بیاور. هر نفوس مرده‌ای که می‌خواهی ببر. اگر می‌خواهی مجانی ببر.»"),
            StoryParagraph("Chichikov, who had expected to haggle for hours, was almost disappointed by how easy the negotiation had been; but he did not complain, because a hundred and twenty dead souls were a hundred and twenty dead souls, no matter how easily they had been acquired.", "چیچیکوف که انتظار داشت ساعت‌ها چانه بزند تقریباً از اینکه مذاکره اینقدر راحت بود ناامید شد؛ اما شکایت نکرد، چون صد و بیست نفس مرده صد و بیست نفس مرده بود، هر چقدر هم راحت به دست آمده باشد."),
            StoryParagraph("When he left Plyushkin's estate, Chichikov felt a strange mixture of triumph and disgust.", "وقتی ملک پلیوشکین را ترک کرد، چیچیکوف آمیزه‌ای عجیب از پیروزی و انزجار حس کرد."),
            StoryParagraph("He had gotten what he wanted, and he had gotten it cheap; but he had also seen, in Plyushkin, what a man could become when he allowed himself to be consumed by his own greed.", "آنچه می‌خواست را گرفته بود و ارزان گرفته بود؛ اما در پلیوشکین دیده بود که انسان وقتی بگذارد طمع خودش بلعدش به چه می‌تواند تبدیل شود."),
            StoryParagraph("'That is what I might become,' he thought, and the thought chilled him.", "فکر کرد: «این همان چیزی است که ممکن است بشوم.» و این فکر سردش کرد."),
            StoryParagraph("'If I am not careful, that is what I might become.'", "«اگر مراقب نباشم، این همان چیزی است که ممکن است بشوم.»"),
            StoryParagraph("But the thought passed, as such thoughts always pass, and Chichikov soon returned to his usual self, counting the dead souls he had acquired and planning the next steps of his great scheme.", "اما فکر گذشت، همانطور که چنین فکرهایی همیشه می‌گذرند و چیچیکوف به‌زودی به خود معمولش برگشت، نفوس مرده‌ای که به دست آورده بود را می‌شمرد و قدم‌های بعدی نقشه بزرگش را برنامه‌ریزی می‌کرد."),
            StoryParagraph("He did not know that his scheme was about to be discovered, that his secret was about to be revealed, that his carefully constructed plan was about to collapse.", "نمی‌دانست که نقشه‌اش در شرف کشف است، رازش در شرف افشا، نقشه دقیق ساخته‌شده‌اش در شرف فروپاشی."),
            StoryParagraph("He did not know that the great and terrible scheme of Chichikov was about to come to an abrupt and humiliating end.", "نمی‌دانست که نقشه بزرگ و هولناک چیچیکوف به‌زودی به پایانی ناگهانی و تحقیرآمیز می‌رسد."),
            StoryParagraph("He did not know that, in a few weeks, he would be forced to flee the province, that his reputation would be destroyed, that his dreams of wealth would be shattered.", "نمی‌دانست که در چند هفته مجبور می‌شود از ولایت فرار کند، آبرویش نابود شود، رؤیاهای ثروتش خرد شود.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Dead Souls, published in 1842, is one of the great works of Russian literature, and one of the most original novels ever written.", "نفوس مرده، منتشرشده در ۱۸۴۲، یکی از آثار بزرگ ادبیات روسیه و یکی از اصیل‌ترین رمان‌های نوشته‌شده است."),
            StoryParagraph("It is subtitled 'A Poem,' and indeed it is more poem than novel, more epic than story, more satire than narrative.", "عنوان فرعی‌اش «منظومه» است و در واقع بیش از رمان، منظومه است، بیش از داستان، حماسه، بیش از روایت، هجو."),
            StoryParagraph("The plot is simple: Chichikov travels through the Russian provinces, buying dead serfs from various landowners, in the hope of mortgaging them for a fortune.", "طرح ساده است: چیچیکوف از ولایات روسیه می‌گذرد و از زمین‌داران مختلف نفوس مرده می‌خرد، به امید گرو گذاشتنشان برای ثروتی."),
            StoryParagraph("But the plot is not the point; the plot is merely the thread upon which Gogol strings his gallery of portraits, each one more grotesque and more truthful than the last.", "اما طرح نکته اصلی نیست؛ طرح تنها رشته‌ای است که گوگول گالری پرتره‌هایش را بر آن می‌بندد، هر یک غریب‌تر و راستین‌تر از قبلی."),
            StoryParagraph("Manilov, the sentimental dreamer; Sobakevich, the cynical brute; Nozdryov, the wild gambler; Plyushkin, the miser consumed by his greed — these are not merely individuals, they are types, and they are types that Russia recognized when the novel was first published.", "مانیلوف، رؤیاپرداز احساساتی؛ سوباکویچ، وحشی بدبین؛ نوزدریوف، قمارباز وحشی؛ پلیوشکین، خسیس بلعیده توسط طمعش — این‌ها تنها افراد نیستند، تیپ‌اند و تیپ‌هایی که روسیه وقتی رمان نخستین بار منتشر شد شناختشان."),
            StoryParagraph("And Chichikov himself, the protagonist, is perhaps the most complex type of all: a man of no particular vice and no particular virtue, a man who is merely clever, who is merely practical, who is merely willing to do whatever is necessary to succeed.", "و خود چیچیکوف، قهرمان داستان، شاید پیچیده‌ترین تیپ از همه باشد: مردی بدون رذیلت خاص و فضیلت خاص، مردی که تنها زرنگ است، تنها عملی است، تنها حاضر است هر کاری برای موفقیت لازم باشد بکند."),
            StoryParagraph("He is not evil, in the sense that the other landowners are evil; he is merely empty, and his emptiness is more terrifying than any evil could be.", "او شرور نیست، به معنایی که سایر زمین‌داران شرورند؛ تنها خالی است و خالی‌بودنش از هر شری هولناک‌تر است."),
            StoryParagraph("Gogol himself called the novel a poem, and he meant it; for him, the novel was not a story but a pilgrimage, not a narrative but a meditation, not a satire but a sermon.", "خود گوگول رمان را منظومه نامید و منظورش بود؛ برای او، رمان داستان نبود بلکه زیارت بود، روایت نبود بلکه مراقبه بود، هجو نبود بلکه موعظه بود."),
            StoryParagraph("He wanted his readers to see, in the gallery of grotesques he had created, a mirror of their own society, and in the mirror, a vision of what Russia might become if it did not change its ways.", "او می‌خواست خوانندگانش در گالری گروتسکی که آفریده بودند، آینه‌ای از جامعه خودشان ببینند و در آینه، بینشی از آنچه روسیه ممکن بود بشود اگر راه‌هایش را عوض نمی‌کرد."),
            StoryParagraph("The novel is also, and perhaps most importantly, a meditation on the Russian soul, on the peculiar character of the Russian people, on the strange and beautiful and terrible place that Russia occupied in the world.", "رمان همچنین، و شاید مهم‌تر از همه، مراقبه‌ای است درباره روح روسی، درباره شخصیت عجیب مردم روس، درباره جایگاه عجیب و زیبا و هولناکی که روسیه در جهان داشت."),
            StoryParagraph("There is a famous passage at the end of the first volume, in which Gogol compares Russia to a troika, a three-horse carriage, flying across the landscape, faster and faster, while the rest of the world watches in amazement.", "بند معروفی در پایان جلد اول هست که گوگول روسیه را با تروئیکا، کالسکه سه‌اسبه، مقایسه می‌کند، در حال پرواز از میان منظره، تندتر و تندتر، در حالی که بقیه جهان با حیرت تماشا می‌کند."),
            StoryParagraph("'Russia, whither are you flying?' the narrator asks. 'Where are you going? The answer comes from nowhere: everything on earth flies by, and other nations and states, casting sidelong glances, step aside and make way for her.'", "راوی می‌پرسد: «روسیه، به کجا می‌پروازی؟ کجا می‌روی؟ پاسخ از هیچ‌جا نمی‌آید: همه چیز روی زمین می‌گذرد و دیگر ملت‌ها و دولت‌ها با نگاه‌های کج کنار می‌روند و راه برایش باز می‌کنند.»"),
            StoryParagraph("This passage is often read as a patriotic hymn, but Gogol's irony is always present, and it is never entirely clear whether he is celebrating Russia or warning her.", "این بند اغلب به‌عنوان سرود میهن‌پرستانه خوانده می‌شود اما طعنه گوگول همیشه حاضر است و هرگز کاملاً روشن نیست که آیا روسیه را جشن می‌گیرد یا هشدارش می‌دهد."),
            StoryParagraph("For Gogol knew, better than most, that Russia's greatness and Russia's tragedy were intertwined, that the same wild vitality that made her fly also made her dangerous, that the same soul that made her beautiful also made her cursed.", "زیرا گوگول بهتر از بیشتران می‌دانست که عظمت روسیه و تراژدی روسیه در هم تنیده‌اند، همان سرزندگی وحشی که او را به پرواز درمی‌آورد هم خطرناکش می‌کند، همان روحی که او را زیبا می‌کند هم نفرینش می‌کند."),
            StoryParagraph("The novel was intended to be the first part of a trilogy, in which Chichikov would be redeemed, would become a better man, would find a way to save his soul.", "قرار بود رمان بخش اول سه‌گانه‌ای باشد که در آن چیچیکوف رستگار شود، مرد بهتری شود، راهی برای نجات روحش بیابد."),
            StoryParagraph("But Gogol never finished the trilogy; he burned the second part, and destroyed the third before it was written, and died in despair, convinced that he had failed in his mission to save Russia through his art.", "اما گوگول هرگز سه‌گانه را تمام نکرد؛ بخش دوم را سوزاند و بخش سوم را پیش از نوشتن نابود کرد و در ناامیدی مرد، مطمئن که در مأموریتش برای نجات روسیه از طریق هنرش شکست خورده."),
            StoryParagraph("And yet the first part survives, and it is enough, because in its pages we find not only the Russia of Gogol's time but the Russia of every time, not only the Russian soul but the human soul, not only a satire but a prophecy.", "و با این حال بخش اول باقی مانده و کافی است، چون در صفحاتش نه تنها روسیه زمان گوگول می‌یابیم بلکه روسیه هر زمان، نه تنها روح روسی بلکه روح انسانی، نه تنها هجایی بلکه پیشگویی."),
            StoryParagraph("For the men whom Chichikov meets on his journey are not merely Russian types; they are types of humanity, and the emptiness at the heart of Chichikov is not merely a Russian emptiness; it is the emptiness of every person who has ever sacrificed everything for the sake of profit.", "زیرا مردانی که چیچیکوف در سفرش ملاقات می‌کند تنها تیپ‌های روسی نیستند؛ تیپ‌های بشریت‌اند و خالی‌بودن قلب چیچیکوف تنها خالی‌بودن روسی نیست؛ خالی‌بودن هر کسی است که هرگز همه چیز را به خاطر سود فدا کرده است."),
            StoryParagraph("Dead Souls is a novel about a man buying dead serfs; but it is also a novel about the death of the soul, about the ways in which we kill our own souls by the lives we choose to lead.", "نفوس مرده رمانی است درباره مردی که نفوس مرده می‌خرد؛ اما رمانی هم هست درباره مرگ روح، درباره شیوه‌هایی که روح خودمان را با زندگی‌هایی که انتخاب می‌کنیم می‌کشیم."),
            StoryParagraph("Chichikov is dead, spiritually; the landowners he visits are dead, morally; the province he travels through is dead, culturally; and Russia itself, Gogol suggests, is dying, slowly and beautifully and tragically.", "چیچیکوف از نظر روحی مرده است؛ زمین‌دارانی که به دیدارشان می‌رود از نظر اخلاقی مرده‌اند؛ ولایتی که از آن می‌گذرد از نظر فرهنگی مرده است؛ و خود روسیه، گوگول پیشنهاد می‌دهد، دارد می‌میرد، آهسته و زیبا و تراژیک."),
            StoryParagraph("And yet, in the very act of describing this death, Gogol gives it life; in the very act of describing this emptiness, he fills it; in the very act of describing this despair, he gives it hope.", "و با این حال، در همان عمل توصیف این مرگ، گوگول به آن زندگی می‌دهد؛ در همان عمل توصیف این خالی‌بودن، پرش می‌کند؛ در همان عمل توصیف این ناامیدی، امیدش می‌دهد."),
            StoryParagraph("Because to describe a thing is to save it, in a way; to name a disease is to begin to cure it; to see a wound is to begin to heal it.", "زیرا توصیف کردن یک چیز به نوعی نجاتش دادن است؛ نامیدن یک بیماری آغاز درمان آن است؛ دیدن یک زخم آغاز شفای آن است."),
            StoryParagraph("Gogol saw the wounds of Russia, and he named them, and he showed them to the world, and in doing so, he became one of the great healers of the Russian soul.", "گوگول زخم‌های روسیه را دید و نامشان برد و به جهان نشانشان داد و در این کار، یکی از شفا دهندگان بزرگ روح روسی شد."),
            StoryParagraph("Dead Souls is not a happy book; it is not a comforting book; it is not a book that offers easy answers to difficult questions.", "نفوس مرده کتاب شادی نیست؛ کتاب تسلی‌بخش نیست؛ کتابی نیست که پاسخ‌های آسان به پرسش‌های دشوار بدهد."),
            StoryParagraph("But it is a true book, and a great book, and a necessary book, and it will continue to be read as long as there are readers who are willing to look into the mirror that Gogol holds up to them.", "اما کتابی راستین است و کتابی بزرگ و کتابی ضروری و تا وقتی خوانندگانی باشند که مایل باشند به آینه‌ای که گوگول برمی‌دارد نگاه کنند خوانده خواهد شد."),
            StoryParagraph("For the mirror does not lie; it shows us what we are, and what we might become, and what we must do to save ourselves.", "زیرا آینه دروغ نمی‌گوید؛ نشانمان می‌دهد چه هستیم و چه می‌توانیم بشویم و چه باید بکنیم تا خودمان را نجات دهیم."),
            StoryParagraph("And what Gogol shows us, in the pages of his great and terrible poem, is this: that the soul can die, but it can also be reborn; that the darkness can descend, but the light can return; that the dead can rise again.", "و آنچه گوگول در صفحات منظومه بزرگ و هولناکش نشانمان می‌دهد این است: روح می‌تواند بمیرد اما می‌تواند دوباره زاده شود؛ تاریکی می‌تواند نازل شود اما نور می‌تواند بازگردد؛ مردگان می‌توانند دوباره برخیزند."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز.")
        )
    )
}